import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{zn as i}from"./chunks/assets.DAjhvrpn.js";var a=JSON.parse(`{"title":"Building a Mini VR Rig","description":"","frontmatter":{"title":"Building a Mini VR Rig","lang":"en-US"},"headers":[],"relativePath":"building/index.md","filePath":"building/index.md"}`),o={name:`building/index.md`};function s(n,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[t(`<h1 id="building-a-mini-vr-rig" tabindex="-1">Building a Mini VR Rig <a class="header-anchor" href="#building-a-mini-vr-rig" aria-label="Permalink to “Building a Mini VR Rig”">​</a></h1><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>This website is the central repository for documentation on <strong>building</strong> the mini virtual reality training rigs as part of BRAIN CoGS at Princeton Neuroscience Institute.</p><p>The building documentation is divided into modules, and each module explains its building process in detail. The STEP files for the entire rig can be downloaded <a href="/building/drawings/Training-mini-VR-rig.step.zip" download>here</a>. The list of parts can be viewed <a href="https://docs.google.com/spreadsheets/d/e/2PACX-1vSSVNJ8194nIha6Z6vqLnmFLNS-IRL88ZfY1aRPxX1KbcyrDNHXVJ4QOEmY1oKVSrLkx7DTxyjK0ceC/pubhtml#" target="_blank" rel="noreferrer">here</a> or <a href="https://docs.google.com/spreadsheets/d/e/2PACX-1vSSVNJ8194nIha6Z6vqLnmFLNS-IRL88ZfY1aRPxX1KbcyrDNHXVJ4QOEmY1oKVSrLkx7DTxyjK0ceC/pub?output=xlsx" target="_blank" rel="noreferrer">downloaded in XLSX format</a>.</p><p>If you need any other file or format, need help, or just want to reach out, don&#39;t hesitate to contact <a href="mailto:jl4459@princeton.edu" target="_blank" rel="noreferrer">Juan Luna</a> or any other member of the BRAIN CoGS team.</p><h2 id="recommended-steps-to-assembly" tabindex="-1">Recommended assembly order <a class="header-anchor" href="#recommended-steps-to-assembly" aria-label="Permalink to “Recommended assembly order”">​</a></h2><ol><li>Begin with the assembly of the bottom part of the cabinet (steps 1-6 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>). In parallel, you can start with the construction of the <a href="/building/projection.html#screen-building">screen</a>.</li><li>Follow the instructions to assemble the <a href="/building/stage.html">stage</a> and <a href="/building/stage.html#stage-installation">install</a> it in the cabinet.</li><li>Screw the <a href="/building/projection.html#mirror">mirror</a> and the <a href="/building/projection.html#screen-assembly">pillars</a>, but not the top plates that will hold the screen.</li><li>Install the <a href="/building/air-supply.html#air-flow-adapter">air supply hose adapter</a> on the side panel (drill the holes in the panel if necessary), then install the side panels on the cabinet (step 8 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>).</li><li>Cut the hole in the back panel for the projector if necessary, install the back panel, slide it down the frame (step 7 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>) and insert the joining strip along the outer edges of the panels.</li><li>Place the adapters on top of the pillars and install the screen (step 2 of <a href="/building/projection.html#screen-assembly">screen assembly</a>).</li><li>Assemble the top portion of the cabinet (step 8 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>).</li><li>Install the DIN rails (step 11 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>) and the <a href="/building/air-supply.html">air supply</a>, <a href="/building/air-puffs.html">air puffs</a> (if used) and <a href="/building/control.html">control</a> modules.</li><li>Install the <a href="/building/positioning.html">positioning system</a> on the rig&#39;s stage.</li><li>Assemble and install the doors (steps 9 and 12 of <a href="/building/cabinet.html#cabinet-assembly">cabinet assembly</a>).</li></ol>`,8)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};